python3 - <<'PY'
import os, fnmatch, subprocess
skip_prefixes = ('/proc','/sys','/dev','/run')
patterns = [
    '*.sql','*.sql.gz','*.dump','*.bak','*.backup','*.sqlite','*.sqlite3','*.db',
    '*.tar','*.tar.gz','*.tgz','*.zip','*.7z','*.gz','*.xz',
    '*backup*','*back_up*','*dump*','*database*','*db-backup*'
]
exclude_prefixes = (
    '/root/.npm/_cacache/', '/usr/share/doc/', '/usr/share/man/', '/usr/share/info/',
    '/usr/lib/node_modules/', '/usr/include/', '/usr/local/lib/python',
)
rows=[]
for root, dirs, files in os.walk('/', topdown=True, onerror=lambda e: None):
    dirs[:] = [d for d in dirs if not os.path.join(root,d).startswith(skip_prefixes)]
    for f in files:
        p=os.path.join(root,f)
        lp=p.lower()
        if any(lp.startswith(x) for x in exclude_prefixes):
            continue
        if any(fnmatch.fnmatch(f.lower(), pat) for pat in patterns):
            try:
                st=os.stat(p)
            except Exception:
                continue
            rows.append((st.st_size, st.st_mtime, p))
rows.sort(reverse=True)
for size, mt, p in rows[:100]:
    try:
        ft=subprocess.check_output(['file','-b',p], text=True, stderr=subprocess.DEVNULL).strip()
    except Exception as e:
        ft='?'
    from datetime import datetime
    print(f'{size}\t{datetime.utcfromtimestamp(mt):%Y-%m-%d %H:%M}\t{p}\t{ft}')
PY
